module min_energy #(\n    parameter MAX_ROWS = 17,  \n    parameter MAX_COLS = 15,\n    parameter COST_WIDTH = 4, \n    parameter DP_WIDTH = 12   \n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] R,  \n    input wire [3:0] C,  \n    input wire signed [COST_WIDTH-1:0] grid [0:MAX_ROWS-1][0:MAX_COLS-1],\n    output reg [DP_WIDTH-1:0] result,\n    output reg done\n);\n\n    reg [DP_WIDTH-1:0] dp [0:MAX_ROWS-1][0:MAX_COLS-1];\n    reg [DP_WIDTH-1:0] next_dp [0:MAX_ROWS-1][0:MAX_COLS-1];\n    reg [4:0] row, col;\n    reg [8:0] iter;\n    reg [2:0] state;\n\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] INIT      = 3'd1;\n    localparam [2:0] RELAX     = 3'd2;\n    localparam [2:0] UPDATE    = 3'd3;\n    localparam [2:0] FIND_MIN  = 3'd4;\n    localparam [2:0] DONE_ST   = 3'd5;\n\n    reg [DP_WIDTH-1:0] candidate;\n    integer n, nr, nc;\n\n    function automatic bit in_bounds(input signed [5:0] r, input signed [5:0] c);\n        in_bounds = (r >= 0 && r < MAX_ROWS && c >= 0 && c < MAX_COLS);\n    endfunction\n\n    function automatic bit is_end(input [4:0] r);\n        is_end = (r == 5'd0);\n    endfunction\n\n    function automatic bit is_start(input [4:0] r);\n        is_start = (r == R + 5'd1);\n    endfunction\n\n    function automatic signed [COST_WIDTH-1:0] get_cost(input [4:0] r, input [4:0] c);\n        if (r == 5'd0 || r == (R + 5'd1))\n            get_cost = 4'd0;\n        else\n            get_cost = grid[r][c];\n    endfunction\n\n    always @(*) begin\n        candidate = dp[row][col];\n        if (is_end(row)) begin\n            candidate = 12'd0;\n        end\n        else begin\n            // Check left\n            nr = row;\n            nc = col - 1;\n            if (in_bounds(nr, nc)) calc_candidate(nr, nc);\n\n            // Check right\n            nr = row;\n            nc = col + 1;\n            if (in_bounds(nr, nc)) calc_candidate(nr, nc);\n\n            // Check up\n            nr = row - 1;\n            nc = col;\n            if (in_bounds(nr, nc)) calc_candidate(nr, nc);\n\n            // Check down\n            nr = row + 1;\n            nc = col;\n            if (in_bounds(nr, nc)) calc_candidate(nr, nc);\n        end\n    end\n\n    task calc_candidate(input integer nr, input integer nc);\n        reg signed [DP_WIDTH:0] sum;\n        reg [DP_WIDTH-1:0] cand;\n        begin\n            sum = $signed(get_cost(nr, nc)) + $signed(dp[nr][nc]);\n            cand = (sum < 0) ? 12'd0 : sum[DP_WIDTH-1:0];\n            if (cand < candidate) candidate = cand;\n        end\n    endtask\n\n    always @(posedge clk or negedge rst_n) begin\n        integer i, j;\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= {DP_WIDTH{1'b0}};\n            state <= IDLE;\n            iter <= 9'd0;\n            row <= 5'd0;\n            col <= 5'd0;\n            for (i = 0; i < MAX_ROWS; i = i + 1) begin\n                for (j = 0; j < MAX_COLS; j = j + 1) begin\n                    dp[i][j] <= {DP_WIDTH{1'b1}};\n                    next_dp[i][j] <= {DP_WIDTH{1'b1}};\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        row <= 5'd0;\n                        col <= 5'd0;\n                    end\n                end\n\n                INIT: begin\n                    if (row < MAX_ROWS) begin\n                        if (is_end(row)) begin\n                            dp[row][col] <= 12'd0;\n                            next_dp[row][col] <= 12'd0;\n                        end else begin\n                            dp[row][col] <= {DP_WIDTH{1'b1}};\n                            next_dp[row][col] <= {DP_WIDTH{1'b1}};\n                        end\n\n                        if (col == (MAX_COLS - 5'd1)) begin\n                            col <= 5'd0;\n                            if (row == (MAX_ROWS - 5'd1)) begin\n                                state <= RELAX;\n                                row <= 5'd0;\n                            end else begin\n                                row <= row + 5'd1;\n                            end\n                        end else begin\n                            col <= col + 5'd1;\n                        end\n                    end\n                end\n\n                RELAX: begin\n                    next_dp[row][col] <= candidate;\n\n                    if (col == (MAX_COLS - 5'd1)) begin\n                        col <= 5'd0;\n                        if (row == (MAX_ROWS - 5'd1)) begin\n                            state <= UPDATE;\n                            row <= 5'd0;\n                        end else begin\n                            row <= row + 5'd1;\n                        end\n                    end else begin\n                        col <= col + 5'd1;\n                    end\n                end\n\n                UPDATE: begin\n                    dp[row][col] <= next_dp[row][col];\n\n                    if (col == (MAX_COLS - 5'd1)) begin\n                        col <= 5'd0;\n                        if (row == (MAX_ROWS - 5'd1)) begin\n                            iter <= iter + 9'd1;\n                            if (iter >= 9'd254) begin\n                                state <= FIND_MIN;\n                                row <= 5'd0;\n                            end else begin\n                                state <= RELAX;\n                                row <= 5'd0;\n                            end\n                        end else begin\n                            row <= row + 5'd1;\n                        end\n                    end else begin\n                        col <= col + 5'd1;\n                    end\n                end\n\n                FIND_MIN: begin\n                    if (col == 5'd0 && row == 5'd0) result <= {DP_WIDTH{1'b1}};\n\n                    if (is_start(row) && dp[row][col] < result)\n                        result <= dp[row][col];\n\n                    if (col == (MAX_COLS - 5'd1)) begin\n                        col <= 5'd0;\n                        if (row == (MAX_ROWS - 5'd1))\n                            state <= DONE_ST;\n                        else\n                            row <= row + 5'd1;\n                    end else begin\n                        col <= col + 5'd1;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule